# ---- THE LEDGERS ----
def ledger(uid, c, lo, hi, title, ps, inks, crowns):
    verses = list(range(lo, hi + 1))
    sif_cites = [f'Sifrei Bamidbar {p}:{r}' for p in ps for r in range(1, SIF_ROWS[p] + 1)]
    cites = [f'Onkelos Num {c}:{v}' for v in verses] + sif_cites
    N = len(cites); NS = len(sif_cites)
    cnt = Counter(R[(c, v)][0] for v in verses); scnt = Counter(S[(p, r)][0] for p in ps for r in range(1, SIF_ROWS[p] + 1))
    mis = [p for p in ps if p in HEAD_FIX]
    sif_decl = (f' + the Sifrei on Numbers piskaot {ps[0]}-{ps[-1]} BY POSITION ({NS} rows at the shelf\'s row grain, fresh — every head asserted between its neighbors' + (f'; the export\'s head{"s" if len(mis) > 1 else ""} on piska {" and ".join(f"{p} reads {heads[p][1]}:{heads[p][2]} for {HEAD_FIX[p][0]}:{HEAD_FIX[p][1]}" for p in mis)} — mistyped, the row placed by position and by its own quotation, RESEARCH_LOG.md' if mis else '') + ')'
                if ps else ' + the Sifrei on Numbers where it has a piska in the span: NONE (computed — the Sifrei opens at 5:1, piska 1; chapter 4 has no row by position)')
    hdr = (f'# Numbers {c}:{lo}-{hi} derivation — Onkelos + the Sifrei on Numbers as the spine (its piskaot found BY POSITION), '
           f'THE NUMBERS WALK sitting 2 — NASO, {title} ({DATE}; the owner: "Go", the sitting after Bamidbar\'s compile, on the ruling NUMBERS IN ORDER FROM 1:1). '
           f'DECLARED (THE_STEPS Step 2, the spine default of 2026-08-27, read at the PARASHAH GRAIN — speed ruling (a): one pass over Naso 4:21-7:89, the seven ledgers per block): scope = Onkelos Numbers {c}:{lo}-{hi} ({len(verses)} verses, fresh)'
           + sif_decl + f'. {TESTING[uid]} OUTSIDE DECLARED SCOPE, enumerated and unread (the shelf\'s other works on Numbers, {len(outside)} directories): {", ".join(outside)}.\n\n')
    body = ''
    if ps:
        body += f'## Sifrei Bamidbar piskaot {ps[0]}-{ps[-1]} ({NS} rows, read whole — the heads by position: {"; ".join(f"{p} on {head(p)[0]}:{head(p)[1]}" for p in ps)})\n'
        for p in ps:
            for r in range(1, SIF_ROWS[p] + 1):
                verdict, prose = S[(p, r)]
                body += f'- Sifrei Bamidbar {p}:{r} — {verdict}. {prose}\n'
        body += '\n'
    else:
        body += '## Sifrei Bamidbar — the shelf\'s silence on Numbers 4:21-49, computed\n(piska 1 opens on 5:1; the export\'s mislabeled piska 62 is 8:24\'s row, read at Bamidbar\'s num_04_kehat; no row of the spine touches 4:21-49 — the shelf\'s, not ours)\n\n'
    body += f'## Onkelos Numbers {c}:{lo}-{hi} ({len(verses)} verses, read whole)\n'
    for v in verses:
        verdict, prose = R[(c, v)]
        body += f'- Onkelos Num {c}:{v} — {verdict}. {prose}\n'
    body += '\n## The ink beside the shelf (computed by this script from the Tanakh DB, the snapshot store and the shelf — never recited)\n'
    for k in inks: body += INK[k] + '\n'
    body += register_line(c, lo, hi) + '\n'
    body += '\n## The finds (this ledger\'s crowns)\n' + '\n'.join(crowns) + '\n'
    body += (f'\n## CITE INDEX — every source opened, each fully named\n(one name per line; coverage COMPUTED against the shelf by the ledger script write_naso_ledgers.py: Onkelos Numbers {c}:{lo}-{hi} {len(verses)} verses — missing 0, extra 0'
             + (f'; the Sifrei on Numbers piskaot {ps[0]}-{ps[-1]}, {NS} rows at the shelf\'s own row counts — missing 0, extra 0' if ps else '; the Sifrei on Numbers holds NO piska on the span by position') + ')\n')
    body += '\n'.join(cites) + '\n'
    body += f'({len(verses)} Onkelos verses fresh' + (f' + {NS} Sifrei Bamidbar rows fresh' if ps else '') + f' = {N} sources in this ledger.)\n\n'
    body += (f'**read: {N} of {N} — COMPLETE** ({len(verses)} Onkelos verses' + (f' and {NS} Sifrei rows' if ps else '') + f' opened and verdicted this sitting at the shelf\'s row grain, coverage computed by script — missing 0, extra 0; '
             f'verdicts MATERIAL {cnt["MATERIAL"]} Onkelos, CONTEXT {cnt["CONTEXT"]} Onkelos' + (f', MATERIAL {scnt["MATERIAL"]} Sifrei, CONTEXT {scnt["CONTEXT"]} Sifrei' if ps else '') + ' — the counts the script\'s own Counter measured)\n')
    open(OUT[uid], 'w', encoding='utf-8').write(hdr + body)
    print(f'wrote {OUT[uid]}: {N} sources, Onkelos MATERIAL {cnt["MATERIAL"]} / CONTEXT {cnt["CONTEXT"]}' + (f'; Sifrei {NS} rows MATERIAL {scnt["MATERIAL"]} / CONTEXT {scnt["CONTEXT"]}' if ps else ''))
    return N, cnt, scnt

